UPDATE ui.dashboardquery SET
vcdashboardquery =  E'
{
  "Transpose": {
    "Customer": "WITH _filtered_data AS (SELECT icustomerid, vcexternalcustid, vccustomername, vccustomertype, vcverifiedname, dtonboardingdate, vcemail, vcregisteredmobile, imcc, vccountrycode, irecordstatus, dtentrydatetime, lastmodified, vcattribs, vcpostalcode, vcsalutation, vcgender, dtdoidob, vcidentitytype1, vcidentitydetails1, vcidentitytype2, vcidentitydetails2, vcregisteredaddressgeolocation FROM t12refined.masters.customers WHERE itenantid = 17 AND dtentrydatetime BETWEEN TIMESTAMP ''2025-01-01 00:00:00'' AND TIMESTAMP ''2025-01-31 23:59:59'' ORDER BY icustomerid DESC LIMIT 50000) SELECT attribute, data FROM _filtered_data CROSS JOIN UNNEST(ARRAY[(''Customer ID'', CAST(icustomerid AS VARCHAR)), (''External Cust ID'', vcexternalcustid), (''Customer Name'', vccustomername), (''Customer Type'', vccustomertype), (''Verified Name'', vcverifiedname), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)), (''Email ID'', vcemail), (''Registered Mobile Number'', vcregisteredmobile), (''MCC'', CAST(imcc AS VARCHAR)), (''Country Code'', vccountrycode), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Last Modified'', CAST(lastmodified AS VARCHAR)), (''KYC'', JSON_EXTRACT_SCALAR(vcattribs, ''$.kyc'')), (''Risk'', JSON_EXTRACT_SCALAR(vcattribs, ''$.risk'')), (''Dealer ID'', JSON_EXTRACT_SCALAR(vcattribs, ''$.dealer_id'')), (''Gross Income'', JSON_EXTRACT_SCALAR(vcattribs, ''$.gross_income'')), (''Source Of Income'', JSON_EXTRACT_SCALAR(vcattribs, ''$.source_of_income'')), (''Termination Status'', JSON_EXTRACT_SCALAR(vcattribs, ''$.termination_status'')), (''Customer Onboarding Type'', JSON_EXTRACT_SCALAR(vcattribs, ''$.customer_onboard_type'')), (''Occupation'', JSON_EXTRACT_SCALAR(vcattribs, ''$.occupation'')), (''City'', JSON_EXTRACT_SCALAR(vcattribs, ''$.city'')), (''State'', JSON_EXTRACT_SCALAR(vcattribs, ''$.state'')), (''Account Type'', JSON_EXTRACT_SCALAR(vcattribs, ''$.accountType'')), (''Gender'', JSON_EXTRACT_SCALAR(vcattribs, ''$.gender'')), (''Account Sub Type'', JSON_EXTRACT_SCALAR(vcattribs, ''$.accountSubType'')), (''DOB'', JSON_EXTRACT_SCALAR(vcattribs, ''$.doi_dob'')), (''Mobile Num Update Time'', JSON_EXTRACT_SCALAR(vcattribs, ''$.Mobile_no_UpdateTime'')), (''Postal Code'', vcpostalcode), (''UCIC ID'', JSON_EXTRACT_SCALAR(vcattribs, ''$.ucic_id'')), (''Salutation'', vcsalutation), (''VC Gender'', vcgender), (''Birth Date'', CAST(dtdoidob AS VARCHAR)), (''Identity Type 1'', vcidentitytype1), (''Identity Detail 1'', vcidentitydetails1), (''Identity Type 2'', vcidentitytype2), (''Identity Detail 2'', vcidentitydetails2), (''Registered Address Geolocation'', vcregisteredaddressgeolocation)]) AS t(attribute, data)",
    "Account": "WITH _filtered_data AS (SELECT iaccountid, icustomerid, vcexternalaccountid, vcaccountname, iaccounttypeid, vcifsc, vcaccount, bverified, imcc, bmerchant, irecordstatus, dtentrydatetime, dtonboardingdate, lastmodified FROM t12refined.masters.accounts WHERE itenantid = 17 AND dtentrydatetime BETWEEN TIMESTAMP ''2025-01-01 00:00:00'' AND TIMESTAMP ''2025-01-31 23:59:59'' ORDER BY iaccountid DESC LIMIT 5000) SELECT attribute, data FROM _filtered_data CROSS JOIN UNNEST(ARRAY[(''Account ID'', CAST(iaccountid AS VARCHAR)), (''Customer ID'', CAST(icustomerid AS VARCHAR)), (''External Account ID'', vcexternalaccountid), (''Account Name'', vcaccountname), (''Account Type'', CAST(iaccounttypeid AS VARCHAR)), (''IFSC'', vcifsc), (''Account Number'', vcaccount), (''Verified'', CAST(bverified AS VARCHAR)), (''MCC'', CAST(imcc AS VARCHAR)), (''Merchant'', CAST(bmerchant AS VARCHAR)), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)), (''Last Modified'', CAST(lastmodified AS VARCHAR))]) AS t(attribute, data)",
    "VPA": "WITH _filtered_data AS (SELECT ivpaid, iaccountid, vcexternaladdressid, vcaddress, vcvpaname, bverified, imcc, bmerchant, irecordstatus, dtentrydatetime, dtonboardingdate, iproductid, dtexpirydate, lastmodified FROM t12refined.masters.vpa WHERE itenantid = 17 AND dtentrydatetime BETWEEN TIMESTAMP ''2025-01-01 00:00:00'' AND TIMESTAMP ''2025-01-31 23:59:59'' ORDER BY ivpaid DESC LIMIT 5000) SELECT attribute, data FROM _filtered_data CROSS JOIN UNNEST(ARRAY[(''VPA ID'', CAST(ivpaid AS VARCHAR)), (''Account ID'', CAST(iaccountid AS VARCHAR)), (''External VPA ID'', vcexternaladdressid), (''VPA'', vcaddress), (''Customer Name'', vcvpaname), (''Verified'', CAST(bverified AS VARCHAR)), (''MCC'', CAST(imcc AS VARCHAR)), (''Merchant'', CAST(bmerchant AS VARCHAR)), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)), (''Product ID'', CAST(iproductid AS VARCHAR)), (''Expires On'', CAST(dtexpirydate AS VARCHAR)), (''Last Modified On'', CAST(lastmodified AS VARCHAR))]) AS t(attribute, data)"
  },
  "Normal": {
    "Customer": "WITH _filtered_data AS (SELECT icustomerid, vcexternalcustid, vccustomername, vccustomertype, vcverifiedname, dtonboardingdate, vcemail, vcregisteredmobile, imcc, vccountrycode, irecordstatus, dtentrydatetime, lastmodified, vcattribs, vcpostalcode, vcsalutation, vcgender, dtdoidob, vcidentitytype1, vcidentitydetails1, vcidentitytype2, vcidentitydetails2, vcregisteredaddressgeolocation FROM t12refined.masters.customers WHERE itenantid = 17 AND dtentrydatetime BETWEEN TIMESTAMP ''2025-01-01 00:00:00'' AND TIMESTAMP ''2025-01-31 23:59:59'' ORDER BY icustomerid DESC LIMIT 5000) SELECT CAST(icustomerid AS VARCHAR) AS \\"Customer ID\\", vcexternalcustid AS \\"External Cust ID\\", vccustomername AS \\"Customer Name\\", vccustomertype AS \\"Customer Type\\", vcverifiedname AS \\"Verified Name\\", CAST(dtonboardingdate AS VARCHAR) AS \\"Onboarding Date\\", vcemail AS \\"Email ID\\", vcregisteredmobile AS \\"Registered Mobile Number\\", CAST(imcc AS VARCHAR) AS \\"MCC\\", vccountrycode AS \\"Country Code\\", CAST(irecordstatus AS VARCHAR) AS \\"Record Status\\", CAST(dtentrydatetime AS VARCHAR) AS \\"Entry Date Time\\", CAST(lastmodified AS VARCHAR) AS \\"Last Modified\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.kyc'') AS \\"KYC\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.risk'') AS \\"Risk\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.dealer_id'') AS \\"Dealer ID\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.gross_income'') AS \\"Gross Income\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.source_of_income'') AS \\"Source Of Income\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.termination_status'') AS \\"Termination Status\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.customer_onboard_type'') AS \\"Customer Onboarding Type\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.occupation'') AS \\"Occupation\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.city'') AS \\"City\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.state'') AS \\"State\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.accountType'') AS \\"Account Type\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.gender'') AS \\"Gender\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.accountSubType'') AS \\"Account Sub Type\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.doi_dob'') AS \\"DOB\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.Mobile_no_UpdateTime'') AS \\"Mobile Num Update Time\\", vcpostalcode AS \\"Postal Code\\", JSON_EXTRACT_SCALAR(vcattribs, ''$.ucic_id'') AS \\"UCIC ID\\", vcsalutation AS \\"Salutation\\", vcgender AS \\"VC Gender\\", CAST(dtdoidob AS VARCHAR) AS \\"Birth Date\\", vcidentitytype1 AS \\"Identity Type 1\\", vcidentitydetails1 AS \\"Identity Detail 1\\", vcidentitytype2 AS \\"Identity Type 2\\", vcidentitydetails2 AS \\"Identity Detail 2\\", vcregisteredaddressgeolocation AS \\"Registered Address Geolocation\\" FROM _filtered_data",
    "Account": "WITH _filtered_data AS (SELECT iaccountid, icustomerid, vcexternalaccountid, vcaccountname, iaccounttypeid, bverified, dtonboardingdate, vcifsc, vcaccount, imcc, bmerchant, irecordstatus, dtentrydatetime, lastmodified FROM t12refined.masters.accounts WHERE itenantid = 17 AND dtentrydatetime BETWEEN TIMESTAMP ''2025-01-01 00:00:00'' AND TIMESTAMP ''2025-01-31 23:59:59'' ORDER BY iaccountid DESC LIMIT 5000) SELECT CAST(iaccountid AS VARCHAR) AS \\"Account ID\\", CAST(icustomerid AS VARCHAR) AS \\"Customer ID\\", vcexternalaccountid AS \\"External Account ID\\", vcaccountname AS \\"Account Name\\", CAST(iaccounttypeid AS VARCHAR) AS \\"Account Type\\", CAST(bverified AS VARCHAR) AS \\"Verified\\", CAST(dtonboardingdate AS VARCHAR) AS \\"Onboarding Date\\", vcifsc AS \\"IFSC\\", vcaccount AS \\"Account Number\\", CAST(imcc AS VARCHAR) AS \\"MCC\\", CAST(bmerchant AS VARCHAR) AS \\"Merchant\\", CAST(irecordstatus AS VARCHAR) AS \\"Record Status\\", CAST(dtentrydatetime AS VARCHAR) AS \\"Entry Date Time\\", CAST(lastmodified AS VARCHAR) AS \\"Last Modified\\" FROM _filtered_data",
    "VPA": "WITH _filtered_data AS (SELECT ivpaid, iaccountid, vcexternaladdressid, vcaddress, vcvpaname, bverified, imcc, bmerchant, irecordstatus, dtentrydatetime, dtonboardingdate, iproductid, dtexpirydate, lastmodified FROM t12refined.masters.vpa WHERE itenantid = 17 AND dtentrydatetime BETWEEN TIMESTAMP ''2025-01-01 00:00:00'' AND TIMESTAMP ''2025-01-31 23:59:59'' ORDER BY ivpaid DESC LIMIT 5000) SELECT CAST(ivpaid AS VARCHAR) AS \\"VPA ID\\", CAST(iaccountid AS VARCHAR) AS \\"Account ID\\", vcexternaladdressid AS \\"External VPA ID\\", vcaddress AS \\"VPA\\", vcvpaname AS \\"Customer Name\\", CAST(bverified AS VARCHAR) AS \\"Verified\\", CAST(imcc AS VARCHAR) AS \\"MCC\\", CAST(bmerchant AS VARCHAR) AS \\"Merchant\\", CAST(irecordstatus AS VARCHAR) AS \\"Record Status\\", CAST(dtentrydatetime AS VARCHAR) AS \\"Entry Date Time\\", CAST(dtonboardingdate AS VARCHAR) AS \\"Onboarding Date\\", CAST(iproductid AS VARCHAR) AS \\"Product ID\\", CAST(dtexpirydate AS VARCHAR) AS \\"Expires On\\", CAST(lastmodified AS VARCHAR) AS \\"Last Modified On\\" FROM _filtered_data"
  }
}'::text WHERE
idashboardqueryid = 164 AND itenantid = 12;





UPDATE ui.dashboardquery SET
vcdashboardquery =  E'
{
  "Transpose": {
    "Customer": "WITH _filtered_data AS (SELECT icustomerid, vcexternalcustid, vccustomername, vccustomertype, vcverifiedname, dtonboardingdate, vcemail, vcregisteredmobile, imcc, vccountrycode, irecordstatus, dtentrydatetime, lastmodified, vcattribs, vcpostalcode, vcsalutation, vcgender, dtdoidob, vcidentitytype1, vcidentitydetails1, vcidentitytype2, vcidentitydetails2, vcregisteredaddressgeolocation FROM t12refined.masters.customers WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN  :StartDate AND :EndDate ORDER BY icustomerid DESC LIMIT 50000) SELECT attribute, data FROM _filtered_data CROSS JOIN UNNEST(ARRAY[(''Customer ID'', CAST(icustomerid AS VARCHAR)), (''External Cust ID'', vcexternalcustid), (''Customer Name'', vccustomername), (''Customer Type'', vccustomertype), (''Verified Name'', vcverifiedname), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)), (''Email ID'', vcemail), (''Registered Mobile Number'', vcregisteredmobile), (''MCC'', CAST(imcc AS VARCHAR)), (''Country Code'', vccountrycode), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Last Modified'', CAST(lastmodified AS VARCHAR)), (''KYC'', JSON_EXTRACT_SCALAR(vcattribs, ''$.kyc'')), (''Risk'', JSON_EXTRACT_SCALAR(vcattribs, ''$.risk'')), (''Dealer ID'', JSON_EXTRACT_SCALAR(vcattribs, ''$.dealer_id'')), (''Gross Income'', JSON_EXTRACT_SCALAR(vcattribs, ''$.gross_income'')), (''Source Of Income'', JSON_EXTRACT_SCALAR(vcattribs, ''$.source_of_income'')), (''Termination Status'', JSON_EXTRACT_SCALAR(vcattribs, ''$.termination_status'')), (''Customer Onboarding Type'', JSON_EXTRACT_SCALAR(vcattribs, ''$.customer_onboard_type'')), (''Occupation'', JSON_EXTRACT_SCALAR(vcattribs, ''$.occupation'')), (''City'', JSON_EXTRACT_SCALAR(vcattribs, ''$.city'')), (''State'', JSON_EXTRACT_SCALAR(vcattribs, ''$.state'')), (''Account Type'', JSON_EXTRACT_SCALAR(vcattribs, ''$.accountType'')), (''Gender'', JSON_EXTRACT_SCALAR(vcattribs, ''$.gender'')), (''Account Sub Type'', JSON_EXTRACT_SCALAR(vcattribs, ''$.accountSubType'')), (''DOB'', JSON_EXTRACT_SCALAR(vcattribs, ''$.doi_dob'')), (''Mobile Num Update Time'', JSON_EXTRACT_SCALAR(vcattribs, ''$.Mobile_no_UpdateTime'')), (''Postal Code'', vcpostalcode), (''UCIC ID'', JSON_EXTRACT_SCALAR(vcattribs, ''$.ucic_id'')), (''Salutation'', vcsalutation), (''VC Gender'', vcgender), (''Birth Date'', CAST(dtdoidob AS VARCHAR)), (''Identity Type 1'', vcidentitytype1), (''Identity Detail 1'', vcidentitydetails1), (''Identity Type 2'', vcidentitytype2), (''Identity Detail 2'', vcidentitydetails2), (''Registered Address Geolocation'', vcregisteredaddressgeolocation)]) AS t(attribute, data)",
    "Account": "WITH _filtered_data AS (SELECT iaccountid, icustomerid, vcexternalaccountid, vcaccountname, iaccounttypeid, vcifsc, vcaccount, bverified, imcc, bmerchant, irecordstatus, dtentrydatetime, dtonboardingdate, lastmodified FROM t12refined.masters.accounts WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN  :StartDate AND :EndDate ORDER BY iaccountid DESC LIMIT 5000) SELECT attribute, data FROM _filtered_data CROSS JOIN UNNEST(ARRAY[(''Account ID'', CAST(iaccountid AS VARCHAR)), (''Customer ID'', CAST(icustomerid AS VARCHAR)), (''External Account ID'', vcexternalaccountid), (''Account Name'', vcaccountname), (''Account Type'', CAST(iaccounttypeid AS VARCHAR)), (''IFSC'', vcifsc), (''Account Number'', vcaccount), (''Verified'', CAST(bverified AS VARCHAR)), (''MCC'', CAST(imcc AS VARCHAR)), (''Merchant'', CAST(bmerchant AS VARCHAR)), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)), (''Last Modified'', CAST(lastmodified AS VARCHAR))]) AS t(attribute, data)",
    "VPA": "WITH _filtered_data AS (SELECT ivpaid, iaccountid, vcexternaladdressid, vcaddress, vcvpaname, bverified, imcc, bmerchant, irecordstatus, dtentrydatetime, dtonboardingdate, iproductid, dtexpirydate, lastmodified FROM t12refined.masters.vpa WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN  :StartDate AND :EndDate ORDER BY ivpaid DESC LIMIT 5000) SELECT attribute, data FROM _filtered_data CROSS JOIN UNNEST(ARRAY[(''VPA ID'', CAST(ivpaid AS VARCHAR)), (''Account ID'', CAST(iaccountid AS VARCHAR)), (''External VPA ID'', vcexternaladdressid), (''VPA'', vcaddress), (''Customer Name'', vcvpaname), (''Verified'', CAST(bverified AS VARCHAR)), (''MCC'', CAST(imcc AS VARCHAR)), (''Merchant'', CAST(bmerchant AS VARCHAR)), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)), (''Product ID'', CAST(iproductid AS VARCHAR)), (''Expires On'', CAST(dtexpirydate AS VARCHAR)), (''Last Modified On'', CAST(lastmodified AS VARCHAR))]) AS t(attribute, data)"
  },
